svg.script:
//
(function() {
  const root = document.getElementById('geriatric-svg-root');
  if (!root) return;

  const nodes = root.querySelectorAll('.interactive-node');
  const panelInfos = root.querySelectorAll('.panel-info');
  const bgRect = root.getElementById('bg-rect');
  const resetBtn = root.getElementById('reset-button');

  function setActive(nodeId) {
    if (!nodeId) {
      root.classList.remove('has-active');
      nodes.forEach(n => {
        n.classList.remove('active');
        n.setAttribute('aria-selected', 'false');
      });
      panelInfos.forEach(p => p.classList.remove('active'));
      const defaultInfo = root.querySelector('[data-target="default"]');
      if (defaultInfo) defaultInfo.classList.add('active');
      return;
    }

    root.classList.add('has-active');
    nodes.forEach(n => {
      if (n.id === nodeId) {
        n.classList.add('active');
        n.setAttribute('aria-selected', 'true');
      } else {
        n.classList.remove('active');
        n.setAttribute('aria-selected', 'false');
      }
    });

    panelInfos.forEach(p => {
      if (p.getAttribute('data-target') === nodeId) {
        p.classList.add('active');
      } else {
        p.classList.remove('active');
      }
    });
  }

  nodes.forEach(node => {
    node.addEventListener('click', (e) => {
      e.stopPropagation();
      setActive(node.id);
    });
    node.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        setActive(node.id);
      }
    });
  });

  if (bgRect) {
    bgRect.addEventListener('click', () => setActive(null));
  }
  if (resetBtn) {
    resetBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      setActive(null);
    });
    resetBtn.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        e.stopPropagation();
        setActive(null);
      }
    });
  }
})();
//
